import{_ as o,h as i,i as e,c as s,v as l,p as n,x as r,m as d,e as C,S as P}from"./chunks/framework.Dvtg8yj2.js";const m=JSON.parse('{"title":"CloudMatrix 384：384×910C + 192 鲲鹏一块超节点","description":"","frontmatter":{"title":"CloudMatrix 384：384×910C + 192 鲲鹏一块超节点","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cloudmatrix-384.md","filePath":"llm/cloudmatrix-384.md","lastUpdated":1788454257000}'),B={name:"llm/cloudmatrix-384.md"};function p(u,a,U,c,E,A){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="cloudmatrix-384-384×910c-192-鲲鹏一块超节点" tabindex="-1">CloudMatrix 384：384×910C + 192 鲲鹏一块超节点 <a class="header-anchor" href="#cloudmatrix-384-384×910c-192-鲲鹏一块超节点" aria-label="Permalink to &quot;CloudMatrix 384：384×910C + 192 鲲鹏一块超节点&quot;">​</a></h1><div class="epigraph"><p>384 颗昇腾 910C 与 192 颗鲲鹏经统一总线收成一个生产级超节点：计算、内存与网络可池化、可统一访问，而不是 48 台各管各的八卡服务器。</p><footer>—— Huawei CloudMatrix384 公开论文：Serving Large Language Models on Huawei CloudMatrix384</footer></div><p>CloudMatrix 384 是华为 CloudMatrix 架构的首个生产级实现。公开材料写明：它集成 <strong>384 个昇腾 910C NPU</strong> 与 <strong>192 个鲲鹏 CPU</strong>，用超高带宽、低时延的统一总线（UB，灵衢）互连，使超节点在逻辑上像一块紧耦合的加速器。物理上覆盖 16 个机柜——12 个计算柜承载 48 个计算节点（48×8=384 颗 910C），4 个通信柜放 L2 UB 交换。本篇钉这组<strong>树标题里的数字与形态</strong>，带宽与封装规格只引用论文已写明的数字，不把 CloudMatrix-Infer 在 DeepSeek-R1 上的 tokens/s 外推成一般定律。对照物是 NVIDIA 把整柜 NVLink 域当成一块 GPU 的讲法，见 <a href="/llm/rack-as-accelerator">机柜作为一块逻辑加速器</a>；两者托盘数、交换与编程栈不可互换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 Atlas 服务器是节点内 8 卡，卡间 HCCS，节点间 RDMA。张量并行、宽专家并行、分布式 KV 一旦跨出节点，就掉到以太网档的延迟与带宽。MoE 的 token dispatch 和长上下文 KV 复用正是这类通信。只加机器台数（Scale-Out）填不满这一档；只加单卡算力，又受封装与供电限制。CloudMatrix 要回答的是：能否把 Scale-Up 域从「一盒 8 卡」拉到「数百 NPU + 配套 CPU」，并且 CPU 内存也能被 NPU 直接用，而不是每条 KV 都先绕主机 PCIe。</p><p>软件若仍按 48 个独立 hostname 调度，UB 买了等于没买。问题与 NVL72 相同：域在硬件上已经是一块，编排必须把域当一份模型并行组。异构之处在于这份组里还有 192 颗鲲鹏，职责不是「再 192 张假 NPU」，而是主机、预处理与可池化的 DRAM。</p><h3 id="_384-与-192-从哪来" tabindex="-1">384 与 192 从哪来 <a class="header-anchor" href="#_384-与-192-从哪来" aria-label="Permalink to &quot;384 与 192 从哪来&quot;">​</a></h3><p>每个计算节点公开配置为 8 个 910C、4 个鲲鹏、7 个板载 L1 UB 交换芯片。48 个计算节点给出 \\(48\\times 8=384\\) 颗 NPU、\\(48\\times 4=192\\) 颗 CPU。不要把 384 理解成 384 个机柜，也不要理解成 384 个 Die 就停——910C 是双 Die 共封装，论文按**封装（NPU 设备）**计数 384；专家并行若「每 Die 一个专家」，Die 数是封装数的两倍，那是另一篇切分账，见后续 CloudMatrix-Infer 树节点，本篇不把 EP320 写进超节点规格。</p><p><span class="marginnote">论文还给出 910C 封装级公开规格：双芯片共封装，每 Die 约 376 TFLOPS 稠密 BF16/FP16，封装合计约 752 TFLOPS；8 个 16 GB 栈共 128 GB 封装内存储，封装级内存带宽约 3.2 TB/s。这些是厂商论文数字，用来理解单卡量级，不是本博客的测量，也不把 384 路相加后的营销 PFLOPS 当成自己测的系统峰值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把一个 CloudMatrix 384 编成一份 Scale-Up 域。域内：TP、延迟敏感的 EP All-to-All、NPU 与 CPU 内存池上的 KV 访问，走 <a href="/llm/ub-lingqu">UB 平面</a>。域间：多个超节点之间的 KV 传递、分布式训练的 DP/PP，走 RDMA 平面（当前为 RoCE）；管控、对象存储、CPU 侧业务走 VPC 平面（擎天网卡，论文写每节点最高约 400 Gbps 单向）。三平面同时存在，是为了和传统数据中心兼容；论文也写了未来把 RDMA 与 VPC 融合的方向，那是规划，不是 384 这代必须已经合一。</p><p>计算节点内，12 个处理器（8 NPU + 4 CPU）经 UB 接到 7 个板载交换，形成单层 UB 平面。论文写：每颗 910C 配置最高约 392 GB/s 单向 UB；每个鲲鹏插槽约 160 GB/s 单向 UB；单颗板载 UB 交换芯片向上一层提供 448 GB/s 上行。只有 NPU 参加 RDMA 平面：每设备额外一条最高 400 Gbps 单向 RDMA，节点合计 3.2 Tbps。四个鲲鹏之间是全网状 NUMA，连接的 DRAM 可统一访问；其中一颗 CPU 挂擎天 DPU，作为南北向出口和节点级资源管理。</p>',12)),(e(),n(P,null,{default:r(()=>[C(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20SN%5B%22CloudMatrix%20384%20%E8%B6%85%E8%8A%82%E7%82%B9%20%3D%20%E4%B8%80%E5%9D%97%E9%80%BB%E8%BE%91%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20subgraph%20CR%5B%2212%20%E8%AE%A1%E7%AE%97%E6%9F%9C%20%C2%B7%2048%20%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20%20%20NPU%5B%22384%20%C3%97%20910C%22%5D%0A%20%20%20%20%20%20CPU%5B%22192%20%C3%97%20%E9%B2%B2%E9%B9%8F%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20COMM%5B%224%20%E9%80%9A%E4%BF%A1%E6%9F%9C%22%5D%0A%20%20%20%20%20%20L2%5B%22L2%20UB%20%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20%20%20end%0A%20%20%20%20NPU%20---%20L2%0A%20%20%20%20CPU%20---%20L2%0A%20%20end%0A%20%20SN%20--%3E%7C%22UB%20%E5%B9%B3%E9%9D%A2%EF%BC%9ATP%20%2F%20EP%20%2F%20%E6%B1%A0%E5%8C%96%E5%86%85%E5%AD%98%22%7C%20UP%5B%22Scale-Up%22%5D%0A%20%20SN%20--%3E%7C%22RDMA%20%E5%B9%B3%E9%9D%A2%EF%BC%9A%E8%B6%85%E8%8A%82%E7%82%B9%E9%97%B4%22%7C%20SO%5B%22Scale-Out%22%5D%0A%20%20SN%20--%3E%7C%22VPC%20%E5%B9%B3%E9%9D%A2%EF%BC%9A%E7%AE%A1%E6%8E%A7%E4%B8%8E%E5%AD%98%E5%82%A8%22%7C%20VPC%5B%22%E6%95%B0%E6%8D%AE%E4%B8%AD%E5%BF%83%E7%BD%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="当作一块加速器来切模型" tabindex="-1">当作一块加速器来切模型 <a class="header-anchor" href="#当作一块加速器来切模型" aria-label="Permalink to &quot;当作一块加速器来切模型&quot;">​</a></h3><p>并行组应落在该 UB 域内：宽 TP、宽 EP 不要在超节点边界上「再拼一台」。论文强调 UB 上点对点全互连，节点间通信性能接近节点内——定量见 <a href="/llm/ub-near-local-perf">带宽衰减与微秒时延</a>。KV 与权重可以按池化内存来设计：NPU HBM 仍是近端最快，CPU DRAM 经 UB 作为第二层，而不是每条请求都打到对象存储。调度上，MatrixResource / MatrixCompute / MatrixContainer 把超节点抽象成可编排实例；业务侧仍应暴露「本作业需要一个 UB 域」，交给 <a href="/llm/hetero-cluster">异构集群调度</a> 去绑，而不是让 Kubernetes 随机抽 8 张卡。</p><p>与 <a href="/llm/scale-up-vs-scale-out">Scale-Up 对 Scale-Out</a> 的对号：384 卡的集合通信属于超节点内；副本、检查点、跨可用区属于超节点外。不要用训练的 3D 切分直接当推理拓扑，decode 更怕跨域 TP。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>逻辑节点成立，靠的是 L1 板载交换加 L2 通信柜的无阻塞结构，以及 UB 同时提供内存语义与消息语义，见 <a href="/llm/ub-l1-l2-planes">L1/L2 七子平面</a> 与 <a href="/llm/ub-lingqu">UB 灵衢</a>。跨柜距离用光模块收口，见 <a href="/llm/ub-optical-cabinets">跨柜光模块</a>。没有这套交换，384 张卡只是 16 柜以太网集群。</p><p>910C 双 Die 通过封装内互连协同（论文给出封装内总带宽约 540 GB/s、单向 270 GB/s 量级）。对软件，一张 910C 仍是一颗 NPU 设备，但有的并行策略按 Die 切专家。不要在容量规划里把 384 与 768 混用而不声明计数单位。</p><p><span class="marginnote">三平面里，UB 连全部 384 NPU 与 192 CPU；RDMA 只有 NPU 参加，把横向流量与管控/存储分开。规划「CPU 是否走 RDMA」时不要默认与 NPU 同一平面。</span></p><h3 id="故障域是超节点" tabindex="-1">故障域是超节点 <a class="header-anchor" href="#故障域是超节点" aria-label="Permalink to &quot;故障域是超节点&quot;">​</a></h3><p>通信柜或一条 L2 子平面影响的是整块逻辑节点的带宽或连通性，不是「少一台 8 卡机」。维护窗口按 16 柜设计：液冷、供电、光模块、交换固件都是域级。集群应能把该超节点从副本集摘掉。论文讨论过更大超节点与 CPU 物理分解，那是后续方向；384 这一代仍是节点内 8+4 的固定配比，逻辑上池化，物理上尚未拆成纯 NPU 柜加纯 CPU 柜。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 NVL72 的 18+9 托盘抄成 CloudMatrix 的 12+4 柜。不要在没有 UB 的普通 8 卡集群上用 64 路 TP「模拟 384」。不要把论文里 DeepSeek-R1 的 prefill 6688 tokens/s/NPU、decode 1943 tokens/s/NPU（TPOT 低于 50 ms）写成任意模型的 SLA——那是指定模型、精度与 CloudMatrix-Infer 软件的测量。不要填写未在论文出现的光模块只数、单通道眼图或未发布的 UB 协议字段。</p><p>超节点增大了爆炸半径与功耗密度，设施规划按柜级功率走厂商交付，不在本文填未核对的千瓦数。软件生态是 CANN / HCCL / MindIE 或 <a href="/llm/vllm-ascend">vLLM-Ascend</a>，迁移成本独立于硬件是否已经是一块逻辑节点。</p><p><span class="marginnote">出处：arXiv:2506.12708 <em>Serving Large Language Models on Huawei CloudMatrix384</em> 中的超节点组成、三平面与节点规格。UB-Mesh 拓扑见 arXiv:2503.20377，本篇只声明 384 的 UB 是其递归落地，不把论文里 4D-Pod 的 1024 NPU 设计与 384 这一 SKU 画等号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CloudMatrix 384 = <strong>384×910C + 192 鲲鹏</strong>，48 计算节点，16 柜（12 计算 + 4 通信），一块 UB 超节点。</li><li>每节点 8 NPU + 4 CPU + 7 L1 交换；NPU 走 UB 与 RDMA，CPU 走 UB 与 VPC 出口。</li><li>域内做 TP/EP 与池化 KV；域间 RoCE；管控存储走 VPC。</li><li>910C 封装规格用论文数字；系统峰值不要用自行连乘的营销口径冒充实测。</li><li>运维按超节点故障域，而不是 48 台独立服务器。</li><li>出处：Huawei CloudMatrix384 公开论文；形态对照 <a href="/llm/scale-up-vs-scale-out">Scale-Up</a>。</li></ul>',15))])}const D=o(B,[["render",p]]);export{m as __pageData,D as default};
